#!/usr/bin/env python3
"""gen_index.py <receipts-dir>: write INDEX.md listing every file present, with size and SHA-256."""
import hashlib
import sys
from pathlib import Path

root = Path(sys.argv[1])
rows = []
for path in sorted(p for p in root.rglob("*") if p.is_file() and p.name != "INDEX.md"):
    data = path.read_bytes()
    rows.append(f"| `{path.relative_to(root)}` | {len(data)} | `{hashlib.sha256(data).hexdigest()}` |")
(root / "INDEX.md").write_text(
    "# Receipts index\n\nGenerated by `scripts/gen_index.py` from the files present.\n\n"
    f"{len(rows)} files.\n\n| File | Bytes | SHA-256 |\n|---|---:|---|\n" + "\n".join(rows) + "\n")
print(len(rows))
